      countryTimeData.locations.forEach((location) => {
        total += location.dates[index][time];
      });
      return {y: time, x: total};
    });
    if (lineChartData.labels.length < 1) {
      lineChartData.labels = sets.map((i) => {
        const d = new Date(i.y.replace(/-/g, '/'));
