export async function fetchData(date) {
  var data = {};
  //console.log(`Fetching data from: ${date}`)
  data = d[date];
  while (
    data === undefined &&
    moment(date, 'MM-DD-YYYY') >= moment('01-22-2020', 'MM-DD-YYYY')
  ) {
    //console.log(`LOCAL data from ${date} not found...attempting to fetch REMOTE data from ${date}`)
    await addRemoteDailyReports(date);
    data = d[date];
    if (data == undefined) {
      //console.log(`REMOTE data from ${date} not found...attempting to fetch LOCAL data from one day before.`)
      date = moment(date, 'MM-DD-YYYY')
        .subtract(1, 'days')
        .format('MM-DD-YYYY');
      data = d[date];
      if (data === undefined) {
        //console.log(`LOCAL data from ${date} not found...attempting to fetch REMOTE data from one day before.`)
        await addRemoteDailyReports(date);
        data = d[date];
      }
    }
  }
  if (data === undefined) {
    data = {error: 'Data not found. Plase try again.'};
  }
  return data;
}

export async function addRemoteDailyReports(date) {
  let locations = [];
  await csv()
    .fromStream(
      request.get(
        `https://raw.githubusercontent.com/CSSEGISandData/COVID-19/master/csse_covid_19_data/csse_covid_19_daily_reports/${date}.csv`,
      ),
    )
    .subscribe(async (json) => {
      return new Promise((resolve, reject) => {
        var obj = {};
        if (moment(date, 'MM-DD-YYYY') <= moment('03-22-2020', 'MM-DD-YYYY')) {
          obj = {
            country: json['Country/Region'] || '',
            state: json['Province/State'] || '',
            lat: json['Latitude'] || '0.0',
            lon: json['Longitude'] || '0.0',
            lastUpdate: json['Last Update'] || '',
            confirmed: parseInt(json['Confirmed']) || 0,
            deaths: parseInt(json['Deaths']) || 0,
            recovered: parseInt(json['Recovered']) || 0,
          };
        } else {
          // console.log('after 03-22-2020');
          obj = {
            country: json['Country_Region'] || '',
            state: json['Province_State'] || '',
            lat: json['Lat'] || '0.0',
            lon: json['Long_'] || '0.0',
            lastUpdate: json['Last_Update'] || '',
            confirmed: parseInt(json['Confirmed']) || 0,
            deaths: parseInt(json['Deaths']) || 0,
            recovered: parseInt(json['Recovered']) || 0,
          };
        }
        locations.push(obj);
        resolve();
      });
    })
    .then(async (json) => {
