export function numberWithCommas(x, shouldRound) {
  const s = x.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  if (shouldRound && x > 999) {
    let decimal = '';
    if (x < 2000 && s.length > 4 && s.slice(-3) !== '000') {
      decimal = `.${s.slice(-3)[0]}`;
    }

    return `${s.slice(0, s.length - 4)}${decimal}K`;
  }
  return s;
}

